void GameWindowTransitionsHandler::setGroup(AsciiString groupName, bool immediate)
{
	ScopedWin32Lock guard((LPCRITICAL_SECTION)m_criticalSectionStorage);
	m_coord1.x = 0;
	m_coord1.y = 0;
	m_coord2.x = TheDisplay->getWidth();
	m_coord2.y = TheDisplay->getHeight();

	if (groupName.isEmpty() && immediate)
	{
		if (m_currentGroup)
		{
			m_currentGroup->retire();
			m_currentGroup = NULL;
		}
	}
	if (immediate && m_currentGroup)
	{
		m_currentGroup->skip();
		m_currentGroup = findGroup(groupName);
		if (m_currentGroup)
			m_currentGroup->init();
		return;
	}

	if (m_currentGroup)
	{
		if (!m_currentGroup->isFireOnce() && !m_currentGroup->isReversed())
			m_currentGroup->reverse();
		m_pendingGroup = findGroup(groupName);
		if (m_pendingGroup)
			m_pendingGroup->init();
		return;
	}

	m_currentGroup = findGroup(groupName);
	if (m_currentGroup)
		m_currentGroup->init();
}


