void GameWindowTransitionsHandler::remove(AsciiString groupName, bool skipPending)
{
	ScopedWin32Lock guard((LPCRITICAL_SECTION)m_criticalSectionStorage);
	TransitionGroup *g = findGroup(groupName);
	if (g)
	{
		if (m_pendingGroup == g)
		{
			if (skipPending)
				m_pendingGroup->skip();

			m_pendingGroup->retire();
			m_pendingGroup = NULL;
		}
		if (m_currentGroup == g)
		{
			m_currentGroup->skip();
			m_currentGroup->retire();
			m_currentGroup = NULL;
			if (m_pendingGroup)
				m_currentGroup = m_pendingGroup;
		}
	}
}


